        for t in output:
            if isinstance(t, (int, float)):
                stack.append(t)
            elif t == 'u+':
                stack[-1] = +stack[-1]
            elif t == 'u-':
                stack[-1] = -stack[-1]
            else:
                r = stack.pop()
                l = stack.pop()
                if t == '+': stack.append(l + r)
                elif t == '-': stack.append(l - r)
                elif t == '*': stack.append(l * r)
                elif t == '/': stack.append(l / r)
                elif t == '%': stack.append(l % r)
                elif t == '**': stack.append(l ** r)

        if len(stack) != 1: raise ValueError("Malformed expression")
        return stack[0]

    try:
        return solve()
    except (IndexError, ZeroDivisionError, OverflowError) as e:
        raise ValueError(str(e))
