import heapq

def topo_lex(graph):
    in_degree = {}
    all_nodes = set()

    # Initialize in_degree and collect all nodes
    for u, successors in graph.items():
        all_nodes.add(u)
        if u not in in_degree:
            in_degree[u] = 0
        for v in successors:
            all_nodes.add(v)
            in_degree[v] = in_degree.get(v, 0) + 1

    # Ensure all nodes are in in_degree map
    for node in all_nodes:
        if node not in in_degree:
            in_degree[node] = 0

    # Min-heap for lexicographical order
    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)

        if u in graph:
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    heapq.heappush(heap, v)

    if len(result) == len(all_nodes):
        return result
    else:
        return None
