  const pending = new Map();
  let inflight = 0;

  const load = (key) => {
    const existing = pending.get(key);

    if (existing) {
      return existing;
    }

    const promise = (async () => {
      try {
        return await loader(key);
      } finally {
        pending.delete(key);
      }
    })();

    pending.set(key, promise);
    inflight++;

    // Return a wrapper to handle the "rejection must not be cached" requirement
    // by ensuring the internal promise is removed from the map immediately 
    // upon settlement (handled by finally) and the caller gets the result/error.
    return promise.catch((err) => {
      pending.delete(key);
      throw err;
    });
  };

  // Re-implementing to ensure the specific "rejection not cached" and 
  // "inflight" logic is perfectly aligned with the requirements.
  const finalLoad = (key) => {
    const existing = pending.get(key);
    if (existing) return existing;

    const p = (async () => {
      try {
        return await loader(key);
      } finally {
        pending.delete(key);
      }
    })();

    pending.set(key, p);
    inflight++;

    // If the loader fails, we must ensure the next call doesn't get the rejected promise.
    // The finally block above handles the deletion. 
    // To ensure a rejection isn't "cached" as a resolved value, 
    // we return the promise directly.
    return p;
  };

  // Refined implementation to strictly meet "rejection is delivered but not cached"
  const finalLoadStrict = (key) => {
    const existing = pending.get(key);
    if (existing) return existing;

    const promise = (async () => {
      try {
        return await loader(key);
      } catch (err) {
        // If it fails, we delete it so it's not cached
        pending.delete(key);
