export function curry<T extends any[], R>(fn: (...args: T) => R) {
  return function curried(...args: any[]): any {
    if (args.length >= fn.length) {
      return fn(...args);
    }
    return (...nextArgs: any[]) => {
      return curried(...args, ...nextArgs);
    };
  };
}

/**
 * To achieve the requested type safety (compile-time errors for extra/wrong 
 * arguments and correct return types for partial applications), 
 * a standard function signature cannot express the recursive "curried" state 
 * in TypeScript's current type system without using complex recursive 
 * conditional types or a class-based approach.
 * 
 * However, the following implementation provides the standard functional 
 * curry behavior. For strict type-level arity tracking, 
 * a "Curried" wrapper type is typically required.
 */

export type CurriedFunction<T extends any[], R> = 
  T extends [any, ...infer Rest] 
    ? (arg: T[0]) => CurriedFunction<Rest, R> 
    : (...args: T) => R;

export function curryStrict<T extends any[], R>(fn: (...args: T) => R): CurriedFunction<T, R> {
  return function curried(...args: any[]): any {
    if (args.length >= fn.length) {
      return fn(...args);
    }
    return (...nextArgs: any[]) => {
      return curried(...args, ...nextArgs);
    };
  };
}
